class A { String f = "fA"; String name() { return "A"; } static String s() { return "sA"; } }
class B extends A { String f = "fB"; @Override String name() { return "B"; } static String s() { return "sB"; } }

A ref = new B();
System.out.println(ref.name() + " " + ref.s() + " " + ref.f);
